# --- 손으로 만든 페이크로 ---

public class FakeMailSendClient implements MailSendClient {
    private final List<String> sentTo = new ArrayList<>();

    @Override
    public boolean sendEmail(String from, String to,
                             String subject, String content) {
        sentTo.add(to);
        return true;
    }

    public List<String> getSentTo() { return sentTo; }
}

@Test
void sendWithFake() {
    // given
    FakeMailSendClient fake = new FakeMailSendClient();
    OrderStatisticsService service = new OrderStatisticsService(
            orderRepository, new MailService(fake, mailSendHistoryRepository));
